import 'package:equatable/equatable.dart';
import '../models/journal_model.dart';
sealed class JournalEvent extends Equatable { const JournalEvent(); @override List<Object?> get props => []; } class LoadJournals extends JournalEvent { const LoadJournals(); } class SelectMood extends JournalEvent { const SelectMood(this.mood); final JournalMood mood; @override List<Object?> get props => [mood]; } class AddJournal extends JournalEvent { const AddJournal({required this.title, required this.transcript, required this.mood, this.audioPath, this.duration = Duration.zero}); final String title; final String transcript; final JournalMood mood; final String? audioPath; final Duration duration; @override List<Object?> get props => [title, transcript, mood, audioPath, duration]; } class DeleteJournalRequested extends JournalEvent { const DeleteJournalRequested(this.id); final String id; @override List<Object?> get props => [id]; } class ToggleFavorite extends JournalEvent { const ToggleFavorite(this.id); final String id; @override List<Object?> get props => [id]; }
